from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,zipfile,hashlib,struct,re
from html.parser import HTMLParser
from urllib.parse import urlsplit,unquote
P=Path(__file__).resolve().parent.parent
scenes=json.loads((P/'scenes.json').read_text())
font=ImageFont.truetype(str(P/'assets/source-semibold.ttf'),24)
small=ImageFont.truetype(str(P/'assets/source-regular.ttf'),18)
for s in scenes:
    ims=[Image.open(P/'images'/f'{s["id"]}-{d}.png').convert('RGB') for d in ('desktop','tablet','mobile')]
    out=Image.new('RGB',(2824,max(im.height for im in ims)+150),'#ede5d1');draw=ImageDraw.Draw(out)
    draw.text((30,22),f'MARGINALIA  /  {s["id"]}  /  {s["title"]}',font=font,fill='#30291e')
    x=25
    for d,im in zip(('Desktop · 1440 × 1000','Tablet · 834 × 1112','Mobile · 390 × 844'),ims):
        draw.text((x,75),d+' CSS · DPR 1',font=small,fill='#6b5c45');out.paste(im,(x,115));x+=im.width+30
    out.save(P/'boards'/f'{s["id"]}.png',optimize=True)
with zipfile.ZipFile(P/'Marginalia-45-mockups.zip','w',zipfile.ZIP_DEFLATED) as z:
    for f in sorted((P/'images').glob('*.png')):z.write(f,'images/'+f.name)
styles='''*{box-sizing:border-box}body{margin:0;background:#faf6ea;color:#30291e;font:16px/1.55 system-ui,sans-serif}header{background:#ede5d1;padding:25px 35px;border-bottom:1px solid #b9ab90}h1{font:32px Georgia,serif;margin:0}p{margin:12px 0}a{color:#744a26}button,select{font:inherit;color:inherit;border:1px solid #867354;border-radius:3px;background:white;padding:10px 15px;cursor:pointer}a:focus-visible,button:focus-visible,select:focus-visible{outline:2px solid #005fcc;outline-offset:4px}.layout{display:grid;grid-template-columns:270px minmax(0,1fr)}aside{padding:20px;background:#fffdf7;border-right:1px solid #b9ab90}aside button{display:block;background:none;border:0;text-align:left;width:100%;font-size:14px;padding:11px 12px}aside button[aria-current=true]{background:#ede5d1;font-weight:600}main{min-width:0;padding:25px}nav{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}.views{display:flex;gap:25px;align-items:flex-start}.device{min-width:0;flex:1}figure{margin:0}figcaption{font-size:13px;margin-bottom:12px}img{width:100%;height:auto;border:1px solid #b9ab90;display:block}.single{display:block}.single .device{max-width:1440px;margin:auto}.single .tablet{max-width:834px}.single .mobile{max-width:390px}.sources{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}footer{border-top:1px solid #b9ab90;margin-top:30px;padding:20px 0;font-size:13px;color:#6b5c45}@media(max-width:900px){.layout{grid-template-columns:1fr}aside{display:flex;overflow:auto;padding:15px}aside button{min-width:190px}main{padding:20px}.views{gap:12px}.sources{gap:12px}}@media(max-width:600px){header{padding:22px}h1{font-size:28px}.views{display:block}.device{margin-bottom:25px}}'''
body='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marginalia · 45 responsive mockups</title><style>'''+styles+'''</style></head><body><header><h1>Marginalia · Books & paper</h1><p>15 connected scenes · 45 independent PNGs · 15 additional boards. Visual references with fictional fixtures.</p><div class="sources"><a href="Marginalia-45-mockups.zip">Download 45 PNGs</a><a href="prototype-index.html">Responsive source</a><a href="README.md">Design handoff</a><a href="comparisons/index.html">Research comparisons</a><a href="comparisons/neutral-structure.html">Neutral structure</a><a href="validation.json">Validation</a></div></header><div class="layout"><aside id="scenes" aria-label="Scenes"></aside><main><h2 id="title"></h2><p id="description"></p><nav aria-label="View device"><button data-device="all">Three devices</button><button data-device="desktop">Desktop</button><button data-device="tablet">Tablet</button><button data-device="mobile">Mobile</button><a id="board">Open board PNG</a><a id="source">Open source</a></nav><div class="views" id="views"></div><footer>1440×1000 · 834×1112 · 390×844 CSS pixels, DPR1. Full-page image heights vary. Captured locally; no live credentials, orders or payments. Click a screen for its full-size PNG.</footer></main></div><script>const scenes='''+json.dumps(scenes,ensure_ascii=False)+''';let selected=location.hash.slice(1)||scenes[0].id,device='all';const aside=document.getElementById('scenes');scenes.forEach(s=>{let b=document.createElement('button');b.textContent=s.id.slice(0,2)+' · '+s.title;b.onclick=()=>{selected=s.id;location.hash=selected;render()};b.dataset.id=s.id;aside.append(b)});document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{device=b.dataset.device;render()});function render(){let s=scenes.find(x=>x.id===selected)||scenes[0];document.getElementById('title').textContent=s.title;document.getElementById('description').textContent=s.description;document.getElementById('board').href='boards/'+s.id+'.png';document.getElementById('source').href=s.source;document.querySelectorAll('[data-id]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.id===s.id)));let v=document.getElementById('views');v.className=device==='all'?'views':'views single';v.innerHTML=(device==='all'?['desktop','tablet','mobile']:[device]).map(d=>'<figure class="device '+d+'"><figcaption>'+d+' · <a href="images/'+s.id+'-'+d+'.png">Full-size PNG</a></figcaption><a href="images/'+s.id+'-'+d+'.png"><img src="images/'+s.id+'-'+d+'.png" alt="'+s.title+' at '+d+'"></a></figure>').join('')}render();</script></body></html>'''
(P/'index.html').write_text(body)
# Comparable-width research displays preserve original reference files.
comp='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marginalia comparison review</title><style>body{font:16px/1.6 system-ui;margin:30px;background:#faf6ea;color:#30291e}h1,h2{font-family:Georgia,serif;font-weight:400}.pair{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:25px 0 45px}img{width:100%;height:auto;border:1px solid #867354}figure{margin:0}figcaption{font-size:14px;margin:10px 0}a{color:#744a26}@media(max-width:750px){.pair{grid-template-columns:1fr}}</style><h1>Marginalia · source comparisons</h1><p>Saved Shopify public captures: 22 October 2026. Local proposed design: v1, 23 October 2026. Equal display widths within each pair; original pixels unchanged. These comparisons do not establish conversion, accessibility or successful cart behavior.</p><p><a href="README.md">Evidence and limitations</a> · <a href="neutral-structure.html">Original neutral task comparison</a> · <a href="../index.html">Storybook</a></p><h2>1 · Publisher collection / Marginalia edition retrieval</h2><div class="pair"><figure><figcaption><a href="https://theme-publisher-demo.myshopify.com/collections/books">Publisher Books</a> · default collection · saved 1440×1000 CSS, DPR1</figcaption><img src="../../../evidence/publisher-collection-desktop.jpg" alt="Saved Publisher books collection"></figure><figure><figcaption>Marginalia scene03 · default subject collection · 1440×1000 CSS, DPR1 · full-page</figcaption><img src="../images/03-collection-desktop.png" alt="Marginalia bibliographic rows"></figure></div><p>Retain title/creator/price and conventional filter entry. Replace large media cards with narrow covers, a subject rail and visible edition/language/binding facts. Required: C typed bibliography/public projection and real paginated facets. Hypothesis: these facts help prevent wrong-edition selection; no user outcome measured.</p><h2>2 · Studio creator discovery / Marginalia reading table</h2><div class="pair"><figure><figcaption><a href="https://theme-studio-demo.myshopify.com/">Studio home</a> · default opening · saved 1440×1000 CSS, DPR1</figcaption><img src="../../../evidence/studio-home-desktop.jpg" alt="Saved Studio creator-led home"></figure><figure><figcaption>Marginalia scene02 · same homepage continuation · 1440×1000 CSS, DPR1 · full-page</figcaption><img src="../images/02-home-bottom-desktop.png" alt="Marginalia author reading table and factual stationery"></figure></div><p>Retain creator-led discovery and intact product proportions. Marginalia pairs author context with books and an independent stationery module; paper size/weight is explicit. Required: A navigation/collection bindings plus C author and stationery facts. The different scroll states are labelled; this pair compares modules rather than equating opening-screen exposure.</p><h2>3 · Studio art PDP / Marginalia reading PDP</h2><div class="pair" style="max-width:850px"><figure><figcaption>Studio seven vessels · saved 390×844 CSS, DPR1 · opening viewport</figcaption><img src="../../../evidence/studio-art-product-mobile.jpg" alt="Saved Studio art product mobile opening"></figure><figure><figcaption>Marginalia scene04 · 390×844 CSS, DPR1 · full-page</figcaption><img src="../images/04-product-main-mobile.png" alt="Marginalia mobile book selection"></figure></div><p>Retain object integrity, named selection and price. A book requires a compact cover, edition/language choice and reading continuation; a stationery product requires paper facts. Studio product recheck was inaccessible to the text web tool; saved evidence remains dated. No remote content is used as Marginalia merchandise.</p><h2>Neutral local captures</h2><p><a href="neutral-01-home-top.png">Home</a> · <a href="neutral-03-collection.png">Collection</a> · <a href="neutral-04-product-main.png">Product</a>. The same source is rendered with imagery, theme branding and color suppressed; bibliographic hierarchy remains.</p></html>'''
(P/'comparisons/index.html').write_text(comp)
print('Packaged 15 boards, ZIP, gallery and comparisons')
